# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List

from rosterkit.errors import ProjectError
from rosterkit.models import Student

def _validate(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students for contact sheet")
    for item in students:
        if not item.email:
            name = item.display_name
            raise ProjectError(f"no email for {name}")

def _layout(pool: List[Student]) -> str:
    name_wid = max(len(item.display_name) for item in pool)
    sect_wid = max(len(item.section) for item in pool)
    return f"{{:<{name_wid}}}  {{:<{sect_wid}}}  {{}}"

def _line(form: str, one: Student) -> str:
    cells = (one.display_name, one.section, one.email)
    return form.format(*cells)

def contact_rows(students: Iterable[Student]) -> List[str]:
    """Rows of name, section and email, sorted by name."""
    pool = list(students)
    _validate(pool)
    pool.sort(key=lambda item: item.display_name.lower())
    form = _layout(pool)
    return [_line(form, one) for one in pool]

