# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student

def make(last, first, section, email):
    return Student("id", last, first, section, email)

MIXED = [
    make("Li", "Al", "A", "al@x.org"),
    make("Johnson", "Bo", "BB", "bo@x.org")
]

ALIGNED = [
    "Johnson, Bo  BB  bo@x.org",
    "Li, Al       A   al@x.org"
]

class ContactRowTests(unittest.TestCase):
    def test_rows_are_sorted_by_name(self):
        rows = contact_rows([
            make("Young", "Zed", "A", "z@x.org"),
            make("Adams", "Amy", "B", "a@x.org")
        ])
        self.assertTrue(rows[0].startswith("Adams, Amy"))
        self.assertTrue(rows[1].startswith("Young, Zed"))

    def test_columns_line_up(self):
        rows = contact_rows(MIXED)
        self.assertEqual(rows, ALIGNED)

    def test_missing_email_names_the_student(self):
        people = [make("Adams", "Amy", "A", None)]
        with self.assertRaises(ProjectError) as caught:
            contact_rows(people)
        self.assertIn("Adams, Amy", str(caught.exception))

    def test_blank_email_is_missing(self):
        with self.assertRaises(ProjectError):
            contact_rows([make("Adams", "Amy", "A", "")])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])

if __name__ == "__main__":
    unittest.main()
